import{u as l,C as s,o as t,c as r,j as o,a,E as d,k as c,e as h,al as u}from"./chunks/framework.7vp1BMOE.js";const m={key:0},b=JSON.parse('{"title":"PX4-Autopilot Main Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"en/releases/main.md","filePath":"en/releases/main.md"}'),p={name:"en/releases/main.md"},v=Object.assign(p,{setup(f){const{site:i}=l();return(_,e)=>{const n=s("Badge");return t(),r("div",null,[e[1]||(e[1]=o("h1",{id:"px4-autopilot-main-release-notes",tabindex:"-1"},[a("PX4-Autopilot Main Release Notes "),o("a",{class:"header-anchor",href:"#px4-autopilot-main-release-notes","aria-label":'Permalink to "PX4-Autopilot Main Release Notes"'},"​")],-1)),d(n,{type:"danger",text:"Alpha"}),c(i).title!=="PX4 Guide (main)"?(t(),r("div",m,[...e[0]||(e[0]=[o("div",{class:"custom-block danger"},[o("p",{class:"custom-block-title"},[a("This page is on a release branch, and hence probably out of date. "),o("a",{href:"https://docs.px4.io/main/en/releases/main"},"See the latest version"),a(".")])],-1)])])):h("",!0),e[2]||(e[2]=u('<p>This contains changes to the PX4 <code>main</code> branch that are not included in the next release (<a href="./../releases/1.18">PX4 v1.18</a>).</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 v1.18 is in beta testing. Update these notes with features that are going to be in <code>main</code> (PX4 v2.0 or later) but not the PX4 v1.18 release.</p></div><h2 id="read-before-upgrading" tabindex="-1">Read Before Upgrading <a class="header-anchor" href="#read-before-upgrading" aria-label="Permalink to &quot;Read Before Upgrading&quot;">​</a></h2><p>Please continue reading for <a href="#upgrade-guide">upgrade instructions</a>.</p><h2 id="major-changes" tabindex="-1">Major Changes <a class="header-anchor" href="#major-changes" aria-label="Permalink to &quot;Major Changes&quot;">​</a></h2><ul><li><strong><a href="./../config/motor_failure_recovery">Motor failure recovery for hexarotors</a>.</strong> On a detected single motor failure the control allocator removes the failed motor and, on a hexarotor, additionally stops (<a href="./../advanced_config/parameter_reference#CA_FAILURE_MODE">CA_FAILURE_MODE</a> = <code>1</code>) or reverses (<code>2</code>) the motor opposite it, recovering the yaw authority that is otherwise lost. Reversing keeps the opposite motor in the allocation and needs a reverse-capable ESC; the reverse thrust the allocator expects from a forward propeller is set with <a href="./../advanced_config/parameter_reference#CA_REV_THR_FRAC">CA_REV_THR_FRAC</a> (default <code>0.4</code>). Disabled by default. (<a href="https://github.com/PX4/PX4-Autopilot/pull/28078" target="_blank" rel="noreferrer">PX4-Autopilot#28078</a>)</li></ul><h2 id="upgrade-guide" tabindex="-1">Upgrade Guide <a class="header-anchor" href="#upgrade-guide" aria-label="Permalink to &quot;Upgrade Guide&quot;">​</a></h2><ul><li><code>COM_ARM_TRAFF</code> has been replaced by <code>COM_TRAFF_AVOID</code>. The old value 3 (&quot;enforce for mission modes only&quot;) is migrated to <code>COM_TRAFF_AVOID=2</code>, which blocks arming in all modes, not just mission modes. If you relied on being able to arm manually with traffic detected, set <code>COM_TRAFF_AVOID=1</code> (warning only) instead.</li><li><code>PCA9685_SCHD_HZ</code> has been removed. <code>PCA9685_PWM_FREQ</code> now sets both the PWM frequency of the PCA9685 and the rate at which values are pushed to it; if you had <code>PCA9685_SCHD_HZ</code> set to a non-default value, set <code>PCA9685_PWM_FREQ</code> to it after upgrading. Frequencies above 400 Hz (previously only usable in duty-cycle mode) are no longer supported.</li><li><strong>Flight controller firmware no longer embeds CAN node firmware.</strong> The <code>px4_fmu-v5_uavcanv0periph</code> build, which carried CUAV CAN GPS v1 firmware in its ROMFS so the flight controller could update the GPS over DroneCAN, and the <code>CONFIG_BOARD_UAVCAN_PERIPHERALS</code> board option behind it have been removed. Use the standard <code>px4_fmu-v5_default</code> firmware and update the GPS from the SD card with <code>cuav_can-gps-v1_default.uavcan.bin</code> from the release instead; see <a href="./../dronecan/#firmware-update">DroneCAN Firmware Update</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/28870" target="_blank" rel="noreferrer">PX4-Autopilot#28870</a>)</li><li><strong>jMAVSim has been removed.</strong> <code>make px4_sitl jmavsim</code> and the <code>10017_jmavsim_iris</code> airframe (<code>SYS_AUTOSTART=10017</code>) no longer exist, and the setup scripts no longer install Java or <code>ant</code>. Use <a href="./../sim_sih/">SIH</a> with the <a href="./../sim_hawkeye/">Hawkeye</a> visualizer instead (<code>make px4_sitl_sih sihsim_quadx</code>), or <a href="./../sim_gazebo_gz/">Gazebo</a>.</li><li><strong>Re-check motor failure handling on hexarotors.</strong> <a href="./../advanced_config/parameter_reference#CA_FAILURE_MODE">CA_FAILURE_MODE</a> = <code>1</code> now also stops the motor opposite the failed one on a hexarotor (previously only the failed motor was removed from the allocation). Other airframes are unaffected, and <code>CA_FAILURE_MODE=0</code> (the default) is unchanged. See <a href="./../config/motor_failure_recovery">Motor Failure Recovery</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/28078" target="_blank" rel="noreferrer">PX4-Autopilot#28078</a>)</li><li><strong>Dual-antenna GNSS heading must be reconfigured.</strong> <code>GPS_YAW_OFFSET</code>, <code>SEP_YAW_OFFS</code>, <code>SEP_PITCH_OFFS</code> and <code>EKF2_GPS_YAW_OFF</code> are removed, including on DroneCAN GNSS nodes, and are not migrated: GNSS yaw is not used until <a href="./../advanced_config/parameter_reference#SENS_GNSS0_HDG">SENS_GNSSn_HDG</a> is set on the autopilot for the receiver reporting the heading. Until then, a warning names what is missing: <code>SENS_GNSSn_HDG</code> or the antenna positions. The baseline comes from the antenna positions (<code>SENS_GNSSn_OFFX/Y/Z</code> of both receivers for a moving base, plus <code>SENS_GNSSn_AUXX/Y/Z</code> for the second antenna of a dual-antenna receiver), and headings whose reported baseline is more than 20% off it are rejected. See <a href="./../gps_compass/rtk_gps#configuring-gps-as-yaw-heading-source">GPS as Yaw/Heading Source</a>. A DroneCAN node running older firmware still subtracts its own <code>GPS_YAW_OFFSET</code>; set that to 0. Heading is taken only from <code>sensor_gnss_relative</code> (u-blox, Unicore UM982, Septentrio, DroneCAN <code>RelPosHeading</code>): the Trimble MB-Two, Femtomes, NMEA <code>HDT</code>, SBG and MicroStrain headings and the heading in DroneCAN <code>Fix2</code> are no longer used, and the <code>heading</code>, <code>heading_offset</code> and <code>heading_accuracy</code> fields of <code>sensor_gps</code> are removed. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27102" target="_blank" rel="noreferrer">PX4-Autopilot#27102</a>)</li><li><strong>GNSS topics, messages and parameters are renamed.</strong> The per-receiver topic <code>sensor_gps</code> is now <code>sensor_gnss</code> (<a href="./../msg_docs/SensorGnss">SensorGnss</a>). <code>vehicle_gps_position</code> is now <code>vehicle_gnss</code> (<a href="./../msg_docs/VehicleGnss">VehicleGnss</a>), which nests the selected receiver&#39;s sample as <code>receiver</code> (for example <code>vehicle_gnss.receiver.latitude</code>) and adds the corrected <code>timestamp_sample</code> and <code>antenna_offset</code>. Renamed fields: <code>latitude_deg</code> → <code>latitude</code>, <code>longitude_deg</code> → <code>longitude</code>, <code>altitude_msl_m</code> → <code>altitude_msl</code>, <code>altitude_ellipsoid_m</code> → <code>altitude_ellipsoid</code>, <code>s_variance_m_s</code> → <code>speed_accuracy</code>, <code>c_variance_rad</code> → <code>course_accuracy</code>, <code>noise_per_ms</code> → <code>noise</code>, <code>vel_m_s</code> → <code>ground_speed</code>, <code>vel_n_m_s</code>/<code>vel_e_m_s</code>/<code>vel_d_m_s</code> → <code>vel_north</code>/<code>vel_east</code>/<code>vel_down</code> and <code>cog_rad</code> → <code>course</code>; <code>antenna_offset_x/y/z</code> moved to <code>vehicle_gnss.antenna_offset</code>. ROS 2 applications must subscribe to <code>/fmu/out/vehicle_gnss</code> (<code>px4_msgs/msg/VehicleGnss</code>) instead of <code>/fmu/out/vehicle_gps_position</code> (<code>px4_msgs/msg/SensorGps</code>). Read the timestamps from the top level of <code>VehicleGnss</code>: only <code>timestamp</code> and <code>timestamp_sample</code> are converted to ROS time, while <code>receiver.timestamp</code> and <code>receiver.timestamp_sample</code> stay on the PX4 boot clock. <code>timestamp</code> is now when the sensors module published the sample; use <code>timestamp_sample</code> for the measurement time. <code>SENS_GPS_MASK</code>, <code>SENS_GPS_TAU</code>, <code>SENS_GPS_PRIME</code> and <code>SENS_GPSn_ID/OFFX/OFFY/OFFZ/DELAY</code> are now <code>SENS_GNSS_*</code> and <code>SENS_GNSSn_*</code> (the driver <code>GPS_*</code> and <code>EKF2_*</code> parameters are unchanged). Saved parameters are migrated automatically, but loading a QGC parameter file with the old names does not restore them. The log analysis scripts in the tree read both the old and the new names. The uORB-over-Cyphal registers are renamed from <code>uorb.sensor_gps</code> to <code>uorb.sensor_gnss</code> (<code>uavcan.sub.uorb.sensor_gnss.0.id</code>, <code>uavcan.pub.uorb.sensor_gnss.0.id</code>); <code>UCAN1_UORB_GPS</code> and <code>UCAN1_UORB_GPS_P</code> are unchanged. (<a href="https://github.com/PX4/PX4-Autopilot/pull/24399" target="_blank" rel="noreferrer">PX4-Autopilot#24399</a>)</li></ul><h2 id="other-changes" tabindex="-1">Other changes <a class="header-anchor" href="#other-changes" aria-label="Permalink to &quot;Other changes&quot;">​</a></h2><ul><li>Fast mission Return modes (<a href="./../advanced_config/parameter_reference#RTL_TYPE">RTL_TYPE</a> = 2 and 4) now skip <code>DO_JUMP</code> commands (loops) while following the mission path. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26993" target="_blank" rel="noreferrer">PX4-Autopilot#26993: fix(navigator): goToNextPositionItem skip loops when required</a>)</li></ul><h3 id="hardware-support" tabindex="-1">Hardware Support <a class="header-anchor" href="#hardware-support" aria-label="Permalink to &quot;Hardware Support&quot;">​</a></h3><ul><li><a href="./../dronecan/escs">DroneCAN ESCs</a> no longer need to set <code>UAVCAN_PUB_ARM</code> as <code>ArmingStatus</code> is published automatically whenever <code>UAVCAN_ENABLE</code> is <code>3</code> (ESC output enabled). (<a href="https://github.com/PX4/PX4-Autopilot/pull/28364" target="_blank" rel="noreferrer">PX4-Autopilot#28364</a>)</li><li><a href="./../dronecan/escs">DroneCAN ESC</a> channels assigned a non-motor function (e.g. <em>Peripheral via Actuator Set</em>) can be driven bidirectionally via <code>UAVCAN_EC_SIGNED</code> (signed RawCommand, 0 = neutral). Motors continue to use <code>CA_R_REV</code>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26903" target="_blank" rel="noreferrer">PX4-Autopilot#26903</a>)</li><li><a href="./../uart/serial_passthrough">Serial Passthrough</a>: new reference <a href="./../uart/serial_passthrough#bridge-application">bridge application</a>, <code>Tools/mavlink_serial_bridge.py</code>, exposes a flight controller serial port or ESC signal pin as a virtual serial port on a Linux/macOS host, so ESC configuration and GPS tools can connect to it over MAVLink. (<a href="https://github.com/PX4/PX4-Autopilot/pull/28782" target="_blank" rel="noreferrer">PX4-Autopilot#28782: feat(tools): add mavlink_serial_bridge.py reference bridge application</a>)</li></ul><h3 id="common" tabindex="-1">Common <a class="header-anchor" href="#common" aria-label="Permalink to &quot;Common&quot;">​</a></h3><ul><li>The unit and functional test suite builds, links and runs on macOS (<code>make tests</code>), and <code>px4_poll()</code> timeouts on macOS wait for their full duration instead of returning at once. The blended GPS timestamp is accumulated in double and rounded once instead of truncating each weighted term. (<a href="https://github.com/PX4/PX4-Autopilot/pull/28516" target="_blank" rel="noreferrer">PX4-Autopilot#28516</a>)</li><li>The AlphaFilter library takes its sample interval and time constant in microseconds, and the float seconds overloads are removed, so a value in the wrong unit no longer compiles. Out-of-tree code that constructs the filter with seconds needs updating. (<a href="https://github.com/PX4/PX4-Autopilot/pull/28421" target="_blank" rel="noreferrer">PX4-Autopilot#28421</a>)</li></ul><h3 id="control" tabindex="-1">Control <a class="header-anchor" href="#control" aria-label="Permalink to &quot;Control&quot;">​</a></h3><ul><li><a href="./../features_mc/gain_compression">Gain compression</a> is now available on multicopters (<a href="./../advanced_config/parameter_reference#MC_GC_EN">MC_GC_EN</a>). When an oscillation is detected on the torque setpoint the rate loop gain is dynamically reduced instead of requiring a manual retune, and recovers to 1.0 once the oscillation stops. The lower bound is set with <a href="./../advanced_config/parameter_reference#MC_GC_GAIN_MIN">MC_GC_GAIN_MIN</a> (default <code>0.3</code>). Disabled by default.</li></ul><h3 id="safety" tabindex="-1">Safety <a class="header-anchor" href="#safety" aria-label="Permalink to &quot;Safety&quot;">​</a></h3><ul><li><a href="./../flight_modes/return#geofence_awareness">Geofence Aware Return mode</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27145" target="_blank" rel="noreferrer">PX4-Autopilot#27145: feat(navigator): Geofence Aware RTL</a>, <a href="https://github.com/PX4/PX4-Autopilot/pull/28001" target="_blank" rel="noreferrer">PX4-Autopilot#28001: docs(navigator): [geofence] added some more warnings about limitations</a>).</li><li><a href="./../advanced_config/flight_termination">Flight termination</a> can now be used instead of a Descent mode as a fallback failsafe mode, allowing safer landing for unpiloted vehicles that carry a parachute. See <a href="./../config/safety#battery-level-failsafe">Battery level failsafe</a> (<a href="./../advanced_config/parameter_reference#COM_LOW_BAT_ACT">COM_LOW_BAT_ACT</a>) and <a href="./../config/safety#position-loss-failsafe-action">Position Loss Failsafe Action</a> (new <a href="./../advanced_config/parameter_reference#COM_POS_FS_ACT">COM_POS_FS_ACT</a>). (<a href="https://github.com/PX4/PX4-Autopilot/pull/28064" target="_blank" rel="noreferrer">PX4-Autopilot#28064: feat(commander): add terminate options for critical battery and lost position failsafes</a>).</li><li><a href="./../debug/failure_injection">Failure injection</a> ( <a href="./../advanced_config/parameter_reference#SYS_FAILURE_EN">SYS_FAILURE_EN</a>) has been significantly extended. (PX4-Autopilot#27572, PX4-Autopilot#27832, PX4-Autopilot#27950) <ul><li>Now applied on real hardware, not just simulators (injection hooks live in the shared sensor drivers).</li><li>Command handling is centralized behind a dedicated failure-injection manager module.</li><li>Multiple sensor instances can be failed simultaneously via a bitmask, and failures can be triggered from an RC switch.</li><li>Changed default behaviour of injected WRONG failure for Batteries, to publish a wrong level, and not stop publishing</li></ul></li><li><a href="./../config/motor_failure_recovery">Motor failure recovery</a> for hexarotors: on a single motor failure the control allocator removes the failed motor and additionally stops (<a href="./../advanced_config/parameter_reference#CA_FAILURE_MODE">CA_FAILURE_MODE</a> = <code>1</code>) or reverses (<code>2</code>) the motor opposite it to recover the lost yaw authority. Mode <code>2</code> requires a reverse-capable ESC and models the reverse thrust of a forward propeller with the new <a href="./../advanced_config/parameter_reference#CA_REV_THR_FRAC">CA_REV_THR_FRAC</a> (default <code>0.4</code>). Reversible motor outputs on DroneCAN are now sent as signed <code>RawCommand</code> values (negative is reverse). (<a href="https://github.com/PX4/PX4-Autopilot/pull/28078" target="_blank" rel="noreferrer">PX4-Autopilot#28078</a>)</li><li>Added <code>RTL_TYPE=6</code> for battery-aware home priority return (<a href="https://github.com/PX4/PX4-Autopilot/pull/26968" target="_blank" rel="noreferrer">PX4-Autopilot#26968</a>). Returns to home if the estimated flight time to home is within the remaining battery time; otherwise returns to the closest rally point. Falls back to the closest safe point (home or rally) if battery time remaining is unavailable.</li></ul><h3 id="estimation" tabindex="-1">Estimation <a class="header-anchor" href="#estimation" aria-label="Permalink to &quot;Estimation&quot;">​</a></h3><ul><li>EKF2 fuses dual-antenna GNSS heading from its own topic, <code>vehicle_gnss_heading</code>, at the heading&#39;s rate and measurement time instead of with each position sample. GNSS yaw fusion is gated on the heading itself (its baseline checks, and the spoofing and jamming state of the receiver providing it under <a href="./../advanced_config/parameter_reference#EKF2_GPS_CHECK">EKF2_GPS_CHECK</a>, which stop it like position fusion), not on the position checks, and it keeps running when position and velocity fusion stop. <code>GPS_RAW_INT</code> and <code>GPS2_RAW</code> report the body-frame heading of the receiver that provides it. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27102" target="_blank" rel="noreferrer">PX4-Autopilot#27102</a>)</li><li>When the local position estimate is lost in flight because of GNSS, commander now reports the reason as an event: either the receiver checks that failed, or that the receiver stopped sending data. The ground station and the log show the cause ahead of the &quot;GNSS data fusion stopped&quot; message. (<a href="https://github.com/PX4/PX4-Autopilot/pull/28873" target="_blank" rel="noreferrer">PX4-Autopilot#28873</a>)</li></ul><h3 id="sensors" tabindex="-1">Sensors <a class="header-anchor" href="#sensors" aria-label="Permalink to &quot;Sensors&quot;">​</a></h3><ul><li>Enable <a href="./../gps_compass/u-center">u-blox Diagnostics with u-center</a> while the vehicle&#39;s GPS runs as usual. (<a href="https://github.com/PX4/PX4-Autopilot/pull/28280" target="_blank" rel="noreferrer">PX4-Autopilot#28280</a>).</li><li>Disabling the selected magnetometer at runtime (setting its <a href="./../advanced_config/parameter_reference#CAL_MAG0_PRIO">CAL_MAGn_PRIO</a> to <code>0</code>) now hands over to the next magnetometer without a sensor failure report, and a magnetometer disabled at boot no longer prevents those after it from being selected. (<a href="https://github.com/PX4/PX4-Autopilot/pull/28750" target="_blank" rel="noreferrer">PX4-Autopilot#28750</a>)</li></ul><h3 id="simulation" tabindex="-1">Simulation <a class="header-anchor" href="#simulation" aria-label="Permalink to &quot;Simulation&quot;">​</a></h3><ul><li>jMAVSim has been removed in favour of <a href="./../sim_sih/">SIH</a> with the <a href="./../sim_hawkeye/">Hawkeye</a> visualizer. See the <a href="#upgrade-guide">Upgrade Guide</a>.</li><li>Gazebo: the GNSS failure injection commands (<code>failure gps off</code>, <code>stuck</code> and <code>wrong</code>) now apply to the NavSat data published by the gz bridge, consistent with the other simulator paths. (<a href="https://github.com/PX4/PX4-Autopilot/pull/28398" target="_blank" rel="noreferrer">PX4-Autopilot#28398</a>)</li></ul><h3 id="debug-logging" tabindex="-1">Debug &amp; Logging <a class="header-anchor" href="#debug-logging" aria-label="Permalink to &quot;Debug &amp; Logging&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="ethernet" tabindex="-1">Ethernet <a class="header-anchor" href="#ethernet" aria-label="Permalink to &quot;Ethernet&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="uxrce-dds-zenoh-ros-2" tabindex="-1">uXRCE-DDS / Zenoh / ROS 2 <a class="header-anchor" href="#uxrce-dds-zenoh-ros-2" aria-label="Permalink to &quot;uXRCE-DDS / Zenoh / ROS 2&quot;">​</a></h3><ul><li>(uXRCE-DDS): SITL multi vehicle automatic namespace prefix is now <code>uav_{px4_instance}</code> and it is aligned with the behaviour of <code>UXRCE_DDS_NS_IDX</code>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/28338" target="_blank" rel="noreferrer">PX4-Autopilot#28338</a>)</li></ul><h3 id="mavlink" tabindex="-1">MAVLink <a class="header-anchor" href="#mavlink" aria-label="Permalink to &quot;MAVLink&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="rc" tabindex="-1">RC <a class="header-anchor" href="#rc" aria-label="Permalink to &quot;RC&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="multi-rotor" tabindex="-1">Multi-Rotor <a class="header-anchor" href="#multi-rotor" aria-label="Permalink to &quot;Multi-Rotor&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="vtol" tabindex="-1">VTOL <a class="header-anchor" href="#vtol" aria-label="Permalink to &quot;VTOL&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="fixed-wing" tabindex="-1">Fixed-wing <a class="header-anchor" href="#fixed-wing" aria-label="Permalink to &quot;Fixed-wing&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="rover" tabindex="-1">Rover <a class="header-anchor" href="#rover" aria-label="Permalink to &quot;Rover&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="ros-2" tabindex="-1">ROS 2 <a class="header-anchor" href="#ros-2" aria-label="Permalink to &quot;ROS 2&quot;">​</a></h3><ul><li>TBD</li></ul>',44))])}}});export{b as __pageData,v as default};
